import sys
from typing import Any

from django.core.exceptions import ValidationError
from django.core.management.base import BaseCommand, CommandError, CommandParser
from django.core.validators import validate_email
from django.utils.crypto import get_random_string

from api.models import User
from librephotos.env import env_str

# Length of an autogenerated password. Replaces the removed
# User.objects.make_random_password(), which defaulted to 10 characters.
GENERATED_PASSWORD_LENGTH = 32


class Command(BaseCommand):
    help = "Create a LibrePhotos user"

    def add_arguments(self, parser: CommandParser) -> None:
        parser.add_argument("username", help="Username to create")
        parser.add_argument("email", help="Email address of the new user")
        parser.add_argument(
            "--password",
            help="Password to create/update for user. (autogenerate if omitted)",
        )
        parser.add_argument(
            "--update",
            help=(
                "Update an existing user's password (ignoring the provided email) "
                "instead of reporting an error"
            ),
            action="store_true",
        )
        parser.add_argument(
            "--admin",
            help="Create user with administrative privileges",
            action="store_true",
        )
        # Done this way because command lines are visible to the whole system by
        #  default on Linux, so a password in the arguments would leak
        parser.epilog = (
            "When creating user with administrative privileges,"
            "the password is read from the ADMIN_PASSWORD"
            "environment variable or interactively if"
            "ADMIN_PASSWORD is not set"
        )

    def handle(self, *args: Any, **options: Any) -> None:
        self._validate_email(options["email"])

        username = options["username"].lower()
        password = self._resolve_password(options)

        if not User.objects.filter(username=username).exists():
            self._create_user(username, options["email"], password, options["admin"])
        elif options["update"]:
            self._update_password(username, options["email"], password)
        else:
            raise CommandError("Specified user already exists")

    def _validate_email(self, email: str) -> None:
        try:
            validate_email(email)
        except ValidationError as err:
            raise CommandError(err.message)

    def _resolve_password(self, options: dict[str, Any]) -> str:
        # Read here rather than in settings, like createadmin does.
        admin_password = env_str("ADMIN_PASSWORD", None)
        if options["admin"] and admin_password is not None:
            options["password"] = admin_password
        if not options["password"]:
            options["password"] = get_random_string(GENERATED_PASSWORD_LENGTH)
        return options["password"]

    def _create_user(
        self, username: str, email: str, password: str, admin: bool
    ) -> None:
        create = User.objects.create_superuser if admin else User.objects.create_user
        create(username, email, password)

    def _update_password(self, username: str, email: str, password: str) -> None:
        print("Warning: ignoring provided email " + email, file=sys.stderr)
        user = User.objects.get(username=username)
        user.set_password(password)
        user.save()
